    for c in range(c_min, c_max + 1):
        if grid[0][c] != 2:
            new_grid[r_min][c] = grid[0][c]

    # Bottom Markers affect the Bottom Row of the 9-region
    for c in range(c_min, c_max + 1):
        if grid[rows-1][c] != 2:
            new_grid[r_max][c] = grid[rows-1][c]

    # Left Markers affect the Left Column of the 9-region
    for r in range(r_min, r_max + 1):
        if grid[r][0] != 2:
            new_grid[r][c_min] = grid[r][0]

    # Right Markers affect the Right Column of the 9-region
    for r in range(r_min, r_max + 1):
        if grid[r][cols-1] != 2:
